import {configuration,defaults} from './model.mjs';
import {normaliseKit,configurationFromURL,toneCaps,builderURL,lesPaul,generatorCapValue,generatorBleedValue} from '../les-paul-kits/config.mjs';
import {deploymentPath} from '../deployment.mjs';
export function generatorURL(state={},kit=null){const q=new URLSearchParams();if(kit){q.set('kit','les-paul');q.set('config',JSON.stringify(normaliseKit(kit)));}q.set('g',JSON.stringify(state));return deploymentPath('/wiring-generator/?'+q);}
export function readGeneratorURL(search){const q=new URLSearchParams(search),kit=configurationFromURL(search);let input={};if(q.has('g')){try{input=JSON.parse(q.get('g'));}catch{throw new Error('This configuration isn’t available yet: the diagram link could not be read.');}}if(kit){const caps=toneCaps(kit);input={...input,guitar:'les-paul',wiring:kit.wiring,bleed:generatorBleedValue(lesPaul.bleed[kit.bleed]),neckCap:generatorCapValue(caps.neck),bridgeCap:generatorCapValue(caps.bridge)};}return {state:configuration(input),kit};}
export function updateKitFromDiagram(kit,state){if(state.guitar!=='les-paul')return null;const caps=toneCaps(kit),next={...kit,wiring:state.wiring};if(generatorBleedValue(lesPaul.bleed[kit.bleed])!==state.bleed)next.bleed=Object.keys(lesPaul.bleed).find(id=>generatorBleedValue(lesPaul.bleed[id])===state.bleed)||'none';if(state.neckCap!==generatorCapValue(caps.neck)||state.bridgeCap!==generatorCapValue(caps.bridge)){const find=value=>Object.keys(lesPaul.capacitors).find(id=>generatorCapValue(lesPaul.capacitors[id])===value);Object.assign(next,{caps:'mixed',neckCap:find(state.neckCap)||kit.neckCap,bridgeCap:find(state.bridgeCap)||kit.bridgeCap});}return normaliseKit(next);}
export function installationGuideURL(state={},kit=null){return generatorURL(state,kit).replace('/wiring-generator/','/luthier-hub/les-paul-installation/');}
export {builderURL};
export function builderDiagramURL(kit,state={}){return builderURL(kit)+'&g='+encodeURIComponent(JSON.stringify(state));}
